  getr R (reg 18) = Z_to_bv 64 (fb + 72) -> getr R (reg 19) = Z_to_bv 64 d -> getr R (reg 20) = Z_to_bv 64 w ->
  getr R (reg 21) = Z_to_bv 64 (fb + 384 + 1) -> kept7 R ->
  0 <= d <= w -> d <= PM.CHUNK -> 1 <= w <= len ->
